// Group tickets by status + calculate metrics
const tickets = $input.all().map(item => item.json);

const byStatus = {};
const byAssignee = {};
let totalDone = 0;
let totalInProgress = 0;
let totalTodo = 0;
let totalBugs = 0;
let highPriority = [];

for (const t of tickets) {
  const status = t.fields?.status?.name || 'Unknown';
  const assignee = t.fields?.assignee?.displayName || 'Unassigned';
  const priority = t.fields?.priority?.name || 'None';
  const issueType = t.fields?.issuetype?.name || 'Task';

  // By status
  if (!byStatus[status]) byStatus[status] = [];
  byStatus[status].push({
    key: t.key,
    summary: t.fields?.summary || '(no title)',
    assignee,
    priority,
    type: issueType
  });

  // By assignee
  if (!byAssignee[assignee]) byAssignee[assignee] = { done: 0, in_progress: 0, todo: 0 };
  if (status.toLowerCase().includes('done') || status.toLowerCase().includes('closed')) {
    byAssignee[assignee].done++;
    totalDone++;
  } else if (status.toLowerCase().includes('progress')) {
    byAssignee[assignee].in_progress++;
    totalInProgress++;
  } else {
    byAssignee[assignee].todo++;
    totalTodo++;
  }

  if (issueType.toLowerCase() === 'bug') totalBugs++;
  if (priority === 'High' || priority === 'Highest') {
    highPriority.push({
      key: t.key,
      summary: t.fields?.summary,
      status,
      assignee
    });
  }
}

const total = tickets.length;
const completionRate = total > 0 ? Math.round((totalDone / total) * 100) : 0;

return {
  json: {
    period: $('Set: Report Period').first().json,
    metrics: {
      total_tickets: total,
      done: totalDone,
      in_progress: totalInProgress,
      todo: totalTodo,
      bugs: totalBugs,
      completion_rate: completionRate,
      high_priority_count: highPriority.length
    },
    by_status: byStatus,
    by_assignee: byAssignee,
    high_priority_tickets: highPriority,
    raw_tickets: tickets.slice(0, 50)
  }
};

// Parse Claude narrative + merge với metrics data
const response = $input.first().json;

let rawText = '';
if (response.message?.content) rawText = response.message.content;
else if (response.content) rawText = typeof response.content === 'string' ? response.content : JSON.stringify(response.content);
else if (response.text) rawText = response.text;
else throw new Error('Cannot find Claude response');

rawText = rawText.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();

let narrative;
try {
  narrative = JSON.parse(rawText);
} catch (e) {
  throw new Error('Claude narrative invalid JSON: ' + rawText.substring(0, 300));
}

const data = $('Code: Aggregate Metrics').first().json;

return {
  json: {
    ...narrative,
    period: data.period,
    metrics: data.metrics,
    by_status: data.by_status,
    by_assignee: data.by_assignee,
    high_priority_tickets: data.high_priority_tickets
  }
};
